#!/usr/bin/env bash
# Generated by `npm run runner:export`. Routes yt-dlp through Cloudflare WARP: YouTube refuses captions and
# downloads from GitHub-hosted runner IPs. `repo` adds the WARP apt source, so Install tools gets cloudflare-warp
# in its one apt-get call; `start` puts WARP behind privoxy (ffmpeg needs an HTTP proxy);
# `rotate` takes a new WARP registration, which usually means a new exit IP; the media-fetch block calls it
# between download retries through AUTOBIZ_NETWORK_RESET_COMMAND.
set -euo pipefail
warp() { warp-cli --accept-tos "$@"; }
case "${1:-}" in
  repo)
    curl -fsSL https://pkg.cloudflareclient.com/pubkey.gpg | sudo gpg --yes --dearmor -o /usr/share/keyrings/cloudflare-warp-archive-keyring.gpg
    echo "deb [signed-by=/usr/share/keyrings/cloudflare-warp-archive-keyring.gpg] https://pkg.cloudflareclient.com/ $(lsb_release -cs) main" | sudo tee /etc/apt/sources.list.d/cloudflare-client.list > /dev/null
    exit 0 ;;
  start)
    echo 'forward-socks5t / 127.0.0.1:40000 .' | sudo tee -a /etc/privoxy/config > /dev/null
    sudo systemctl restart privoxy
    mkdir -p "$HOME/.config/yt-dlp"
    echo '--proxy http://127.0.0.1:8118' > "$HOME/.config/yt-dlp/config"
    warp registration new && warp mode proxy && warp connect ;;
  rotate)
    warp disconnect || true
    warp registration delete || true
    warp registration new && warp mode proxy && warp connect ;;
  *) echo "usage: warp.sh repo|start|rotate" >&2; exit 2 ;;
esac
for _ in $(seq 1 30); do
  if curl -sf -x http://127.0.0.1:8118 https://www.cloudflare.com/cdn-cgi/trace | grep -E '^(warp|colo)='; then exit 0; fi
  sleep 1
done
echo "WARP did not come up" >&2
exit 1
